"""Evaluation card: one Markdown evidence pack per run, generated by Python from saved results.

It follows the shape of Model Cards (Mitchell et al. 2019) and Datasheets (Gebru et al. 2021) and keeps
the fields that NIST AI RMF MEASURE 2.1 and EU AI Act Article 15 ask a team to document: test sets,
metrics, tools, declared accuracy and its limits. It supports documentation. It does not establish
compliance and it is not a safety approval. No model writes any number here.
"""
from __future__ import annotations

from typing import Any

from blindspot_ci.experiment import release_gate
from blindspot_ci.experiment.power import cases_needed, upper_bound_no_failures
from blindspot_ci.experiment.scoring import MIN_SLICE_FOR_CLAIM

LIMITS = [
    "Scoring uses box overlap against one human box. There is no mask-quality metric and SAM returned no confidence scores.",
    "Each case is one photo. A pass is one example that met the threshold, not a guarantee for that condition.",
    "Small slices have wide intervals. Report counts with their interval, never a bare percentage.",
    "Labels were not independently re-checked unless a reviewer is named in label_provenance.",
    "Results hold for the listed model versions, prompts and date only.",
]


def _pct(value: float) -> str:
    return f"{round(value * 100)}%"


def _rate(row: dict[str, Any]) -> str:
    if not row["scored"]:
        return "n/a"
    lo, hi = row["pass_ci95"]
    return f"{row['passed']} of {row['scored']} ({_pct(lo)} to {_pct(hi)})"


def _cell(text: Any) -> str:
    return str(text).replace("|", "/").replace("\n", " ")


def _order_sentence(planner: Any) -> str:
    """Say who set the test order, using only the planner recorded in the run."""
    if planner is None or not str(planner).strip():
        return "Test order recorded in the run was used."
    name = str(planner).upper()
    if "MUSE" in name:
        return "A Muse Spark agent picks each test by function calling and sees earlier results."
    if "MOCK" in name:
        return ("Tests followed a fixed scripted order from a simulated mock planner. "
                "The simulated planner applies set rules to earlier results.")
    if "HEURISTIC" in name:
        return "Tests followed a heuristic order set by plain Python rules."
    if "SCRIPT" in name:
        return "Tests followed a fixed scripted order."
    return "Test order recorded in the run was used."


def build_card(run: dict[str, Any]) -> str:
    summary, dataset = run["summary"], run["dataset"]
    steps = run.get("steps", [])
    notes = run.get("reviewer_notes", [])
    audit = run.get("audit")
    provenance = [(s.get("ground_truth") or {}).get("label_provenance") or {} for s in steps]
    annotators = sorted({p.get("annotator", "unknown") for p in provenance} or {"unknown"})
    licenses = sorted({str(p["license"]) for p in provenance if p.get("license")})
    reviewed = sum(1 for p in provenance if p.get("reviewer"))
    flags: list[str] = []
    if run["mode"].endswith("MOCK_FIXTURE"):
        flags.append("This run used scripted mock answers. It shows the software working and says nothing about SAM.")
    kind = dataset["type"]
    if "SYNTHETIC" in kind:
        flags.append("The images are programmatic drawings. This is a plumbing check, not evidence about SAM.")
    if kind.startswith("GENERATED"):
        flags.append("The images were generated by Muse Image and their boxes were inherited, not re-verified.")
    if run["mode"].startswith("CACHE"):
        flags.append("Some answers were replayed from a saved earlier call.")
    planner = run.get("planner")
    lines = [
        f"# Evaluation card: run {run['id']}", "",
        (f"Mode: {run['mode']}. Planner: {planner or 'not recorded'}. Model under test: {run['model']}. "
         f"Started: {run['started_at']}."), ""]
    if flags:
        lines += ["## Read this first", ""] + [f"- {f}" for f in flags] + [""]
    lines += [
        "## Intended use", "",
        ("Find tested conditions where the segmentation model misses or misplaces an object, so a person "
         "knows what to check next. This is one bounded evaluation, not a safety approval."), "",
        "## Evidence", "",
        f"- Dataset: {dataset['id']} ({kind}).",
        f"- Annotation status: {dataset['annotation_status']}.",
        f"- Label sources: {', '.join(annotators)}.",
        f"- Image licenses: {', '.join(licenses) if licenses else 'not recorded'}.",
        f"- Cases tested: {summary['tested']}. Cases with a named reviewer: {reviewed} of {len(steps)}.",
        f"- Unknown (not scored): {summary['unknown']}. Errors (not scored): {summary['errors']}.", "",
        "## Method", "",
        (f"{_order_sentence(planner)} SAM 3.1 segments "
         "the photo. Python scores the best box against the human box. A case passes when the best IoU is "
         f"at least {run['min_iou']}, or when nothing is returned for an absent label. Intervals are 95 percent "
         "Wilson score intervals (Brown, Cai and DasGupta 2001)."), "",
        "## Results", "",
        "| Slice | Passed of scored (95% interval) | Evidence |", "| --- | --- | --- |",
        f"| all tests | {_rate(summary)} | {'underpowered' if summary['underpowered'] else 'ok'} |"]
    for name, row in summary["by_condition"].items():
        lines.append(f"| {_cell(name)} | {_rate(row)} | "
                     f"{'underpowered: fewer than ' + str(MIN_SLICE_FOR_CLAIM) + ' scored' if row['underpowered'] else 'ok'} |")
    lines += ["", "## What this sample can show", "",
              (f"- With {summary['scored']} scored cases and no failures, the 95% upper bound on the failure rate "
               f"would be {upper_bound_no_failures(summary['scored']) * 100:.1f}%. Failures raise it."),
              ("- To claim a failure rate below 5%, 1% or 0.1% with 95% confidence you need "
               f"{cases_needed(0.05)}, {cases_needed(0.01)} or {cases_needed(0.001)} failure-free independent "
               "cases in the slice you make the claim about."),
              "- Photos from one scene or clip are not independent. Count scenes, not frames."]
    failed = [s for s in steps if s["outcome"]["status"].startswith("FAIL")]
    lines += ["", "## Failures", ""]
    if failed:
        lines += ["| Case | Condition | Status | IoU | Why |", "| --- | --- | --- | --- | --- |"]
        lines += [f"| {_cell(s['case']['id'])} | {_cell(s['case']['condition'])} | {s['outcome']['status']} | "
                  f"{s['outcome']['iou']} | {_cell(s['outcome']['reason'])} |" for s in failed]
    else:
        lines.append("No failures among the tests that ran. That is not proof the other conditions are safe.")
    if notes:
        lines += ["", "## Reviewer notes", ""]
        lines += [f"- {n['case_id']} ({n['source']}): {_cell(n['text'])}" for n in notes]
    if audit:
        lines += ["", "## Audit text", "", f"Written by {audit['model']} from the saved results. It changes no score.", "",
                  "```text", audit["text"].replace("```", "'''"), "```"]
    gate = release_gate.evaluate(run, release_gate.load_policy(None), None)
    lines += ["", "## Release gate", "", f"Decision: {gate['decision']}"]
    if gate.get("reason"):
        lines.append(f"Reason: {_cell(gate['reason'])}")
    lines += ["", "Failing checks", ""]
    failing_checks = [check for check in gate["checks"] if check["status"] == "FAIL"]
    lines += [f"- {check['status']}: {check['name']}: {_cell(check['detail'])}" for check in failing_checks]
    if not failing_checks:
        lines.append("None.")
    lines += ["", "Recommended next experiments", ""]
    lines += [f"- {_cell(item)}" for item in gate["next_experiments"]] or ["- None."]
    lines += ["", gate["notice"]]
    lines += ["", "## Reproducibility", "",
              f"- Run id {run['id']}. Calls {run['calls']}. Estimated cost ${run['estimated_cost_usd']}.",
              f"- Pass threshold: IoU {run['min_iou']}."]
    lines += [f"- {s['case']['id']}: image sha256 {s['image_sha256'][:16]}, source "
              f"{(s['prediction'] or {}).get('source', 'none')}, model {(s['prediction'] or {}).get('model', 'none')}."
              for s in steps]
    lines += ["", "## Known limits", ""] + [f"- {item}" for item in LIMITS]
    lines += ["", "## Where this fits", "",
              "- Model Cards and Datasheets: intended use, evaluation data, metrics and limits are stated above.",
              "- NIST AI RMF MEASURE 2.1: test sets, metrics and tools are documented here.",
              ("- EU AI Act Article 15: declared metrics and their limits. This supports documentation only and "
               "does not establish compliance."), ""]
    return "\n".join(lines)
